var a=[{title:`Proteggi l’essenziale`,text:`Per prima cosa decidi a cosa serve principalmente la sessione, come la pratica della forza o il condizionamento aerobico. Dedica un paio di minuti a riscaldare i movimenti che userai, poi concentrati su uno o due esercizi principali. Una sessione breve ha comunque bisogno di spazio per una tecnica sicura e di un riposo sufficiente quando i carichi sono pesanti.`},{title:`Formati che fanno risparmiare tempo`,text:`I superset abbinano esercizi che non competono, come rematori e squat, e le serie alternate riducono i tempi di attesa. I circuiti possono concatenare movimenti semplici per la forma generale. Non avere fretta tra sollevamenti pesanti e tecnici se la fatica comincia a costarti controllo.`},{title:`Esempio`,text:`Per una sessione total body di 15 minuti, riscaldati brevemente, alterna due o tre serie controllate di squat alla sedia e push-up inclinati, poi finisci con un rematore o un plank. Regola ripetizioni e riposo su ciò che riesci a fare ora. Un altro giorno, una camminata veloce o una pedalata facile possono sostenere il tuo condizionamento.`},{title:`Le attività brevi si sommano`,text:`Le attività brevi contano per il tuo totale settimanale. Allunga le sessioni solo quando aiuta e si adatta alla tua vita. Quando non sono possibili blocchi più lunghi, sessioni brevi e regolari possono mantenere efficace la tua routine.`},{title:`Usare TrainUp`,text:`Imposta in Profilo la durata della sessione e i giorni di allenamento preferiti in modo che corrispondano al tempo che hai davvero, e modificali ogni volta che il tuo programma cambia.`}];var o=[{label:`Indicazioni pratiche ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`},{label:`NHS: camminare per la salute`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`}];var t={sections:a,sources:o};export{t as default,a as sections,o as sources};